parameters.new_string:
import { db } from './db';
import { toggleNotifications } from './actions';

export default function Home() {
  const isEnabled = db.notificationsEnabled;

  return (
    <main>
      <h1>Notification Settings</h1>
      <p>Current Status: <strong>{isEnabled ? 'Enabled' : 'Disabled'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}
